24	struct cfl_array *cfl_array_create(size_t slot_count)
25	{
26	    struct cfl_array *array;
27	
28	    array = malloc(sizeof(struct cfl_array));
29	    if (array == NULL) {
30	        cfl_errno();
31	        return NULL;
32	    }
33	
34	    /* by default arrays are not resizable */
35	    array->resizable = CFL_FALSE;
36	
37	    /* allocate fixed number of entries */
38	    array->entries = calloc(slot_count, sizeof(void *));
39	    if (array->entries == NULL) {
40	        cfl_errno();
41	        free(array);
42	        return NULL;
43	    }
44	
45	    array->entry_count = 0;
46	    array->slot_count = slot_count;
47	
48	    return array;
49	}
50	
51	void cfl_array_destroy(struct cfl_array *array)
52	{
53	    size_t index;
54	
55	    if (!array) {
56	        return;
57	    }
58	
59	    if (array->entries != NULL) {
60	        for (index = 0 ; index < array->entry_count ; index++) {
61	            if(array->entries[index] != NULL) {
62	                cfl_variant_destroy(array->entries[index]);
63	            }
64	        }
65	
66	        free(array->entries);
67	    }
68	    free(array);
69	}
70	
71	int cfl_array_resizable(struct cfl_array *array, int v)
72	{
73	    if (v != CFL_TRUE && v != CFL_FALSE) {
74	        return -1;
75	    }
76	
77	    array->resizable = v;
78	    return 0;
79	}
80	
81	int cfl_array_remove_by_index(struct cfl_array *array,
82	                              size_t position)
83	{
84	    if (position >= array->entry_count) {
85	        return -1;
86	    }
87	
88	    cfl_variant_destroy(array->entries[position]);
89	
90	    if (position != array->entry_count - 1) {
91	        memmove(&array->entries[position],
92	                &array->entries[position + 1],
