41	cfl_sds_t sds_alloc(size_t size)
42	{
43	    void *buf;
44	    cfl_sds_t s;
45	    struct cfl_sds *head;
46	
47	    buf = malloc(CFL_SDS_HEADER_SIZE + size + 1);
48	    if (!buf) {
49	        return NULL;
50	    }
51	
52	    head = buf;
53	    head->len = 0;
54	    head->alloc = size;
55	
56	    s = head->buf;
57	    *s = '\0';
58	
59	    return s;
60	}
