        instance->data.as_bytes = value;
    }
    else {
        if (length > INT_MAX) {
            free(instance);
            return NULL;
        }

        instance->data.as_bytes = cfl_sds_create_len(value, (int) length);
        if (instance->data.as_bytes == NULL) {
            free(instance);
            return NULL;
        }
    }
    cfl_variant_size_set(instance, length);
    instance->type = CFL_VARIANT_BYTES;

    return instance;
